    "wrong": "Косая слоистость в разрезе всегда показывает одно течение, идущее в одну сторону.",
    "right": "В приливном рукаве косые слои могут показывать два противоположных направления течения (бимодальность).",
    "claims": ["c7", "c8"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Направления косых слоёв в разрезе, по которым видно, куда шёл поток.", "claims": ["c5", "c7"], "hypothesis": false},
      {"text": "Смена фаций по вертикали и частота мелких смен.", "claims": ["c7"], "hypothesis": false},
      {"text": "Ходы илоедов и корневые следы в глинах.", "claims": ["c2", "c3"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Вывод о приливном влиянии, если в разрезе есть два противоположных направления течения.", "claims": ["c7"], "hypothesis": false},
      {"text": "Вывод, что верх разреза относится к зоне мангровых болот.", "claims": ["c3"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Мелкие и частые колебания: одно направление слоя может не отражать общий поток.", "claims": ["c6", "c8"], "hypothesis": true},
      {"text": "Прибрежные каналы кончаются баровыми песками, поэтому верх разреза зависит от места.", "claims": ["c4"], "hypothesis": false}
    ]
  },
  "it_analogy": {
